<?php
namespace App\Services; final class ATSAnalyzer { public function scan(array $resume,string $job=''): array { $text=strtolower(json_encode($resume)); $score=0; $cats=[]; $rules=['contact'=>['email','phone'],'sections'=>['experience','education','skills'],'formatting'=>['summary'],'impact'=>['achieved','improved','led','built','managed']]; foreach($rules as $name=>$words){ $hits=0; foreach($words as $w) if(str_contains($text,$w)) $hits++; $pct=(int)round($hits/max(1,count($words))*100); $cats[$name]=$pct; $score += min(25,$pct/4); } $missing=[]; if($job){ foreach(array_unique(str_word_count(strtolower($job),1)) as $kw){ if(strlen($kw)>5 && !str_contains($text,$kw)) $missing[]=$kw; if(count($missing)>12) break; }} return ['score'=>(int)min(100,$score),'categories'=>$cats,'missing_keywords'=>$missing,'recommendations'=>['Use standard section headings.','Add measurable impact where accurate.','Include relevant job keywords only when truthful.'],'disclaimer'=>'Estimated optimization score only; it does not guarantee ATS results.']; }}
